/* The shell's data, generated by scripts/build-portal.mjs from the repo's files. Typed here once. */
import raw from '../data/portal.json';
import rawUsage from '../data/usage.json';

/** A published dashboard. Unpublished ones never reach the portal (see scripts/build-portal.mjs). */
export type Dashboard = {
  id: string;
  title: string;
  owner: string | null;
  audience: string | null;
  /** The day of its last verify run, YYYY-MM-DD. */
  verified: string | null;
  numbers: string[];
  filters: string[];
  widgets: number;
  refresh: string | null;
};
export type Recipe = {
  id: string;
  status: 'CONFIRMED' | 'DRAFT';
  meaning: string;
  owner: string | null;
  excludes: string | null;
  format: string | null;
  dashboards: string[];
};
export type Role = { id: string; groups: string[]; note: string };

/** One dashboard's figures for a range of days. How each is counted: scripts/usage.mjs. */
export type UsageRange = {
  people: number;
  prevPeople: number;
  opens: number;
  prevOpens: number;
  cameBack: number;
  /** Most people first. The id is a role id; blank when the role was not known. */
  roles: { id: string; people: number }[];
  busiest: { date: string; people: number } | null;
  /** The busiest weekday (0 Monday) and the first of the two busiest hours in a row. */
  when: { weekday: number; hour: number } | null;
  /** Opens by weekday (Monday first) and hour: hours[weekday][hour]. */
  hours: number[][];
};
export type DashboardUsage = {
  /** The day it was last opened, YYYY-MM-DD. null: never. */
  last: string | null;
  /** The 90 days to `asOf`, oldest first. */
  days: { from: string; people: number[]; opens: number[] };
  /** The same 90 days in 13 weeks counted back from `asOf`, oldest first. The oldest week has 6 days. */
  weeks: { people: number[]; opens: number[] };
  ranges: Record<UsageDays, UsageRange>;
};
export type UsageDays = 7 | 30 | 90;

const data = raw as unknown as { from: string; dashboards: Dashboard[]; recipes: Recipe[]; roles: Role[] };

export const { dashboards, recipes, roles } = data;
/** Who opened what. `asOf` is the day of the newest open on record; null means the portal records no usage yet. */
export const usage = rawUsage as unknown as { asOf: string | null; dashboards: Record<string, DashboardUsage> };
export const dataFrom = data.from;
export const dashboardById = (id: string) => dashboards.find((d) => d.id === id) ?? null;
export const recipeById = (id: string) => recipes.find((r) => r.id === id) ?? null;

/** head_of_treasury -> Head of treasury. For ids the files hold; never used on their words. */
export const humanize = (id: string) => {
  const s = id.replace(/^kpi\./, '').replace(/[_-]+/g, ' ').trim();
  return s.charAt(0).toUpperCase() + s.slice(1);
};
